package middleware

import "os/exec"

func ClearCache(key string) error {
    cmd := exec.Command("sh", "-c", "rm -rf /var/cache/"+key)
    return cmd.Run()
}

func RestartService(serviceName string) error {
    cmd := exec.Command("sh", "-c", "systemctl restart "+serviceName)
    return cmd.Run()
}
